import pytest
from jarvis.core import text as T
@pytest.mark.parametrize('n,gender,expected',[(0,'m','ноль'),(1,'m','один'),(1,'f','одна'),(2,'f','две'),(11,'m','одиннадцать'),(21,'f','двадцать одна'),(40,'m','сорок'),(50,'m','пятьдесят'),(60,'m','шестьдесят'),(70,'m','семьдесят'),(80,'m','восемьдесят'),(90,'m','девяносто'),(100,'m','сто'),(101,'f','сто одна'),(1000,'m','одна тысяча'),(2000,'m','две тысячи'),(5000,'m','пять тысяч'),(1000000,'m','один миллион'),(-21,'m','минус двадцать один')])
def test_numbers(n,gender,expected):assert T.num_ru(n,gender)==expected
@pytest.mark.parametrize('n,expected',[(0,'нуля'),(1,'одного'),(2,'двух'),(3,'трёх'),(4,'четырёх'),(11,'одиннадцати'),(21,'двадцати одного'),(40,'сорока'),(50,'пятидесяти'),(60,'шестидесяти'),(70,'семидесяти'),(80,'восьмидесяти'),(90,'девяноста'),(100,'ста'),(200,'двухсот'),(150,'ста пятидесяти'),(1000,'одной тысячи'),(2000,'двух тысяч'),(1000000,'одного миллиона')])
def test_genitive(n,expected):assert T.num_ru_gen(n)==expected
@pytest.mark.parametrize('n,expected',[(0,'задач'),(1,'задача'),(2,'задачи'),(4,'задачи'),(5,'задач'),(11,'задач'),(12,'задач'),(14,'задач'),(21,'задача'),(22,'задачи'),(25,'задач'),(101,'задача'),(111,'задач')])
def test_plural(n,expected):assert T.plural(n,'задача','задачи','задач')==expected
@pytest.mark.parametrize('h,m,expected',[(0,0,'ноль часов ровно'),(1,1,'один час одна минута'),(2,2,'два часа две минуты'),(5,5,'пять часов пять минут'),(8,2,'восемь часов две минуты'),(10,7,'десять часов семь минут'),(11,11,'одиннадцать часов одиннадцать минут'),(21,21,'двадцать один час двадцать одна минута'),(23,59,'двадцать три часа пятьдесят девять минут')])
def test_time(h,m,expected):assert T.time_words(h,m)==expected
@pytest.mark.parametrize('text,expected',[('1 г','один грамм'),('2 грамма','два грамма'),('5 граммов','пять граммов'),('21 ккал','двадцать одна килокалория'),('3500 ккал','три тысячи пятьсот килокалорий'),('до 50 граммов','до пятидесяти граммов'),('около 100 граммов','около ста граммов'),('более 200 граммов','более двухсот граммов'),('2 задачи','две задачи'),('11 задач','одиннадцать задач'),('150.0 г','сто пятьдесят граммов'),('1,5 г','одна целая пять десятых грамма')])
def test_units(text,expected):assert T.normalize_full_units(text)==expected
@pytest.mark.parametrize('text,expected',[('уточняю','уточн+яю'),('календаре','календар+е'),('календарь','календ+арь'),('календаря','календар+я'),('календарём','календарём'),('пятидесяти','пят+идесяти'),('шестидесяти','шест+идесяти'),('семидесяти','сем+идесяти'),('восьмидесяти','восьм+идесяти'),('на связи','на св+язи'),('белка','белк+а'),('белку','белк+у'),('граммов','гр+аммов'),('килокалорий','килокал+орий'),('осталось','ост+алось')])
def test_stresses(text,expected):assert T.apply_dict(text,{})==expected
@pytest.mark.parametrize('text',['Уточняю: в календаре осталось 2 задачи.','По данным на 10:07, сэр. Осталось до 50 граммов белка.','Я на связи, сэр.'])
def test_pipeline_no_model(text):
 result=T.normalize(text,{},accent=None)
 assert isinstance(result,str) and result


@pytest.mark.parametrize('src,out', [('Тесты зелёные.', 'Тэсты зелёные.'), ('запуск тестов', 'запуск тэстов'),
                                     ('тестирование', 'тестирование'), ('тест', 'тэст'), ('протесты', 'протесты')])
def test_tests_pronounced_with_hard_t(src, out):
    assert T.pronounce(src) == out


def test_slushayu_stressed_on_first_syllable():
    out = T.normalize('Слушаю, сэр. Тесты прошли.', {}, accent=None)
    assert 'Сл+ушаю' in out and 'Т+эсты' in out
